declare(strict_types=1);require_once dirname(__DIR__).'/common.php';require_once __DIR__.'/storage.php';require_once __DIR__.'/lab-core.php';lab_admin();
function lab_inherit_rules(PDO $db,string $genre):array {$rules=['common'=>[],'genre'=>[]];$allow=['titleFormat','fixRule','descRules','communityRules','thumbImage','thumbFont','thumbDecor','thumbLayout','youtubeSeo','sunoLimit','outputOrder','thumbCastRule','lang','langRule','titleMode','titleModeRule','focus','reality','motion','extra','sunoBase','vocalStyle','musicStyle','rewriteRules','structure','moodLineRule','thumbGenreLine','forbidList','guideText','output','actOutput','lockDescLyrics','lockRule','matchRule','community','descLyrics','actPlaylist'];foreach(['common'=>'사용자설정/공통.json','genre'=>'사용자설정/장르/'.$genre.'.json'] as $name=>$path){$q=$db->prepare('SELECT sha256,source_bytes FROM noa_source_files WHERE path_hash=?');$q->execute([hash('sha256',$path)]);$row=$q->fetch(PDO::FETCH_ASSOC);if($row&&hash('sha256',$row['source_bytes'])===$row['sha256'])$rules[$name]=array_intersect_key(json_decode($row['source_bytes'],true,512,JSON_THROW_ON_ERROR),array_flip($allow));$q=$db->prepare("SELECT payload FROM noa_documents WHERE doc_key=? AND kind='prefs'");$q->execute(['pref:'.($name==='common'?'__common':$genre)]);$payload=$q->fetchColumn();if($payload!==false)$rules[$name]=array_replace($rules[$name],array_intersect_key(json_decode($payload,true,512,JSON_THROW_ON_ERROR),array_flip($allow)));}return $rules;}
try{
 $method=$_SERVER['REQUEST_METHOD']??'GET';$db=noa_bridge_pdo();
 if($method==='GET'){ $genre=(string)($_GET['genre']??'kpop-original');if(!preg_match('/^[a-z0-9-]{1,60}$/D',$genre))throw new InvalidArgumentException('invalid_genre');lab_json(200,['rules'=>lab_inherit_rules($db,$genre)]);}
 if($method!=='POST')lab_json(405,['error'=>'method_not_allowed']);lab_csrf();$b=lab_json_body();$operation=$b['operation']??'';if(!in_array($operation,['package','plan','lyrics','revise','hook','suno','translate','content','thumbnail'],true))throw new InvalidArgumentException('invalid_operation');$request=lab_id((string)($b['requestId']??''));$genre=(string)($b['genre']??'');if(!preg_match('/^[a-z0-9-]{1,60}$/D',$genre))throw new InvalidArgumentException('invalid_genre');$prompt=$b['prompt']??'';if(!is_string($prompt)||trim($prompt)===''||mb_strlen($prompt)>8000)throw new InvalidArgumentException('invalid_prompt');$language=(string)($b['language']??'ko');if(!in_array($language,['ko','en','ja','th'],true))throw new InvalidArgumentException('invalid_language');$cast=(string)($b['cast']??'female');if(!in_array($cast,['female','male','duet'],true))throw new InvalidArgumentException('invalid_cast');$track=(string)($b['trackKey']??'');$snapshot=['genreId'=>$genre,'title'=>'AI 제작 초안','body'=>[]];$sourceRevision=0;if($track!==''){$q=$db->prepare("SELECT payload,revision FROM noa_documents WHERE doc_key=? AND kind IN ('single','playlist','story')");$q->execute([$track]);$row=$q->fetch(PDO::FETCH_ASSOC);if(!$row)throw new InvalidArgumentException('unknown_track');$snapshot=json_decode($row['payload'],true,512,JSON_THROW_ON_ERROR);$sourceRevision=(int)$row['revision'];}
 $rules=lab_inherit_rules($db,$genre);$result=lab_lock(function(&$s)use($request,$genre,$prompt,$operation,$language,$cast,$track,$snapshot,$sourceRevision,$rules,$b){foreach($s['jobs'] as $existing)if(($existing['requestId']??'')===$request)return ['job'=>lab_public_job($existing),'replayed'=>true];if(count($s['jobs'])>=200)throw new DomainException('job_limit');$secret=lab_unseal($s['secrets']??null);if(empty($secret['openaiKey'])||empty($s['config']['textEnabled']))throw new DomainException('text_ai_enable_required');$today=gmdate('Y-m-d');$sum=0;foreach($s['jobs'] as $j)if(substr($j['costReservedAt']??'',0,10)===$today)$sum+=(float)($j['costReservedUsd']??0);if(($s['config']['maxJobUsd']??0)<.1||$sum+.1>($s['config']['dailyBudgetUsd']??0))throw new DomainException('text_budget_exceeded');$id=bin2hex(random_bytes(16));mkdir(lab_job_dir($id),0700);$job=['id'=>$id,'requestId'=>$request,'type'=>'creation','title'=>$snapshot['title']?:'AI 제작 초안','trackKey'=>$track,'snapshot'=>$snapshot,'sourceRevision'=>$sourceRevision,'genre'=>$genre,'cast'=>$cast,'state'=>'queued_text','revision'=>1,'createdAt'=>gmdate('c'),'updatedAt'=>gmdate('c'),'attempts'=>0,'outputs'=>[],'settings'=>['mode'=>'text','posting'=>'save','formats'=>[]],'creationRequest'=>['operation'=>$operation,'prompt'=>$prompt,'language'=>$language,'rules'=>$rules,'additionalRules'=>substr((string)($s['config']['creativeRules']??''),0,12000),'structure'=>substr((string)($b['structure']??''),0,2000),'mood'=>substr((string)($b['mood']??''),0,1000)],'costReservedUsd'=>.1,'costReservedAt'=>gmdate('c')];$s['jobs'][$id]=$job;lab_event($s,'creation_requested',$id,(string)$GLOBALS['member']['mb_id']);return ['job'=>lab_public_job($job)];});lab_json(200,$result);
}catch(DomainException $e){lab_json(409,['error'=>$e->getMessage()]);}catch(InvalidArgumentException $e){lab_json(400,['error'=>$e->getMessage()]);}catch(Throwable $e){error_log('[noa-creator] '.get_class($e));lab_json(503,['error'=>'creation_unavailable']);}
